  3	// Callback-style database access. Chapter 5 migrates this to UserRepository.
  4	export function findByEmail(email, callback) {
  5	  query('users', (u) => u.email === email && u.deleted_at === null, (err, rows) => {
  6	    if (err) return callback(err);
  7	    callback(null, rows[0] ?? null);
  8	  });
  9	}
 10	
 11	export function isActive(email, callback) {
 12	  findByEmail(email, (err, user) => {
 13	    if (err) return callback(err);
 14	    callback(null, Boolean(user));
 15	  });
 16	}
 17	// A router with no framework, so the project has an HTTP surface to survey
 18	// in Chapter 1's rate-limiting example without an Express dependency.
 19	import { listActiveUsers, findUser } from '../services/user-service.js';
 20	import { listOrdersForUser, totalPaidCents } from '../services/order-service.js';
 21	import { uncapturedTotalCents } from '../services/payment-service.js';
 22	
 23	export const routes = [
 24	  { method: 'GET', path: '/users', handler: (req, cb) => listActiveUsers(cb) },
 25	  { method: 'GET', path: '/users/:id', handler: (req, cb) => findUser(Number(req.params.id), cb) },
 26	  { method: 'GET', path: '/users/:id/orders', handler: (req, cb) => listOrdersForUser(Number(req.params.id), cb) },
 27	  { method: 'GET', path: '/reports/paid-total', handler: (req, cb) => totalPaidCents(cb) },
 28	  { method: 'GET', path: '/reports/uncaptured-total', handler: (req, cb) => uncapturedTotalCents(cb) },
 29	];
 30	
 31	export function listEndpoints() {
 32	  return routes.map((r) => `${r.method} ${r.path}`);
 33	}
 34	// A deliberately tiny in-memory database with a callback API.
 35	// The callback style is the point: Chapter 5 migrates the service layer off it.
 36	
 37	const tables = {
 38	  users: [
 39	    { id: 1, email: 'ada@example.com', name: 'Ada', deleted_at: null },
 40	    { id: 2, email: 'grace@example.com', name: 'Grace', deleted_at: null },
 41	    { id: 3, email: 'alan@example.com', name: 'Alan', deleted_at: '2026-01-04' },
 42	  ],
 43	  orders: [
 44	    { id: 10, user_id: 1, total_cents: 4200, status: 'paid', deleted_at: null },
 45	    { id: 11, user_id: 1, total_cents: 1350, status: 'quote', deleted_at: null },
 46	    { id: 12, user_id: 2, total_cents: 9900, status: 'paid', deleted_at: null },
 47	    { id: 13, user_id: 3, total_cents: 500, status: 'paid', deleted_at: null },
 48	  ],
 49	  payments: [
 50	    { id: 100, order_id: 10, amount_cents: 4200, captured: true },
 51	    { id: 101, order_id: 12, amount_cents: 9900, captured: false },
 52	  ],
 53	};
 54	
 55	export function reset() {
 56	  tables.users[2].deleted_at = '2026-01-04';
 57	  tables.orders.forEach((o) => { o.deleted_at = null; });
 58	}
 59	
 60	// Old-style callback query. Accepts a table name and a predicate.
 61	export function query(table, predicate, callback) {
 62	  setImmediate(() => {
 63	    const rows = tables[table];
 64	    if (!rows) return callback(new Error(`no such table: ${table}`));
 65	    try {
 66	      callback(null, rows.filter(predicate).map((r) => ({ ...r })));
 67	    } catch (err) {
 68	      callback(err);
 69	    }
 70	  });
 71	}
 72	
 73	export function update(table, id, patch, callback) {
 74	  setImmediate(() => {
 75	    const row = (tables[table] || []).find((r) => r.id === id);
 76	    if (!row) return callback(new Error(`no row ${id} in ${table}`));
 77	    Object.assign(row, patch);
 78	    callback(null, { ...row });
 79	  });
 80	}
 81	import { query, update } from '../db.js';
 82	
 83	// The repository pattern the project is migrating toward: promise-based,
 84	// one place per table, no query construction anywhere else.
 85	export class UserRepository {
 86	  findActive() {
 87	    return new Promise((resolve, reject) => {
 88	      query('users', (u) => u.deleted_at === null, (err, rows) =>
 89	        err ? reject(err) : resolve(rows));
 90	    });
 91	  }
 92	
 93	  findById(id) {
 94	    return new Promise((resolve, reject) => {
 95	      query('users', (u) => u.id === id, (err, rows) =>
 96	        err ? reject(err) : resolve(rows[0] ?? null));
 97	    });
 98	  }
 99	
100	  softDelete(id, when) {
101	    return new Promise((resolve, reject) => {
102	      update('users', id, { deleted_at: when }, (err, row) =>
103	        err ? reject(err) : resolve(row));
104	    });
105	  }
106	}
107	import { test } from 'node:test';
108	import assert from 'node:assert/strict';
109	import { findByEmail, isActive } from '../src/services/auth-service.js';
110	
111	test('findByEmail ignores soft-deleted users', (t, done) => {
112	  findByEmail('alan@example.com', (err, user) => {
113	    assert.equal(err, null);
114	    assert.equal(user, null);
115	    done();
116	  });
117	});
118	
119	test('isActive is true for a live user', (t, done) => {
120	  isActive('ada@example.com', (err, active) => {
121	    assert.equal(err, null);
122	    assert.equal(active, true);
123	    done();
124	  });
125	});

